{"command":"cat > gen_b64.py << 'EOF'
import numpy as np
import base64
import sys

def sine_wave(freq, duration, sample_rate=44100):
    t = np.linspace(0, duration, int(sample_rate * duration), False)
    wave = np.sin(2 * np.pi * freq * t)
    audio = np.int16(wave * 32767)
    return base64.b64encode(audio.tobytes()).decode('ascii')

def square_wave(freq, duration, sample_rate=44100):
    t = np.linspace(0, duration, int(sample_rate * duration), False)
    wave = np.sign(np.sin(2 * np.pi * freq * t))
    audio = np.int16(wave * 32767)
    return base64.b64encode(audio.tobytes()).decode('ascii')

def noise_wave(duration, sample_rate=44100):
    np.random.seed(42)
    audio = np.random.randint(-32768, 32767, size=int(sample_rate * duration), dtype=np.int16)
    return base64.b64encode(audio.tobytes()).decode('ascii')

if __name__ == '__main__':
    if sys.argv[1] == 'sine':
        print(sine_wave(float(sys.argv[2]), float(sys.argv[3])))
    elif sys.argv[1] == 'square':
        print(square_wave(float(sys.argv[2]), float(sys.argv[3])))
    elif sys.argv[1] == 'noise':
        print(noise_wave(float(sys.argv[2])))
EOF"}

